def donut(values,labels,center,caption,colors=None):
 colors=colors or ['#e7835c','#b7a5c8','#a6b9a3','#eac489','#d8b2a6','#9ab5c4','#d6ccbe'];total=sum(values);offset=0;parts='';legend=''
 for v,l,c in zip(values,labels,colors):
  frac=v/total*100;parts+=f'<circle cx="155" cy="155" r="113" fill="none" stroke="{c}" stroke-width="40" pathLength="100" stroke-dasharray="{frac} {100-frac}" stroke-dashoffset="{-offset}" transform="rotate(-90 155 155)"/>';offset+=frac
  legend+=f'<div><i style="background:{c}"></i><span>{l}</span><b>{v:g}</b></div>'
 return f'<div class="donut-layout"><svg viewBox="0 0 310 310" role="img" aria-label="{caption}">{parts}<text x="155" y="150" text-anchor="middle" font-size="36" font-weight="800" fill="#51453d">{center}</text><text x="155" y="180" text-anchor="middle" font-size="15" fill="#796c63">{caption}</text></svg><div class="chart-legend">{legend}</div></div>'
def hbars(labels,values,unit='',maxv=None):
 maximum=maxv or max(values)
 return '<div class="warm-bars">'+''.join(f'<div><span>{l}</span><div><i style="width:{v/maximum*100}%"></i></div><b>{v:g}{unit}</b></div>' for l,v in zip(labels,values))+'</div>'
def linechart(labels,values,caption):
 maximum=math.ceil(max(values)/50)*50;coords=[(65+i*120,330-v/maximum*275) for i,v in enumerate(values)]
 gridlines=''.join(f'<line x1="50" y1="{330-j*275/4}" x2="590" y2="{330-j*275/4}" stroke="#dfd5c8"/><text x="40" y="{335-j*275/4}" text-anchor="end" font-size="13" fill="#8b7b6c">{maximum*j/4:g}</text>' for j in range(5))
 points=' '.join(f'{x},{y}' for x,y in coords)
 items=''.join(f'<circle cx="{x}" cy="{y}" r="7" fill="#df7c56"/><text x="{x}" y="{y-18}" text-anchor="middle" font-size="22" fill="#78442d" font-weight="700">{v:.1f}</text><text x="{x}" y="365" text-anchor="middle" font-size="16" fill="#76695e">{l}</text>' for (x,y),l,v in zip(coords,labels,values))
 return f'<svg viewBox="0 0 650 400" class="warm-line" role="img" aria-label="{caption}">{gridlines}<polyline points="{points}" fill="none" stroke="#df7c56" stroke-width="4" stroke-dasharray="9 5"/>{items}<text x="325" y="395" text-anchor="middle" font-size="13" fill="#8a7766">{caption}</text></svg>'
